from math import gcd

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def lcm_list(numbers):
    if not numbers:
        return 1
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = lcm(result, numbers[i])
    return result

def gcd_list(numbers):
    if not numbers:
        return 0
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = gcd(result, numbers[i])
    return result

sequence = [1, 2, 3, 6]
n = len(sequence)
good_partitions = 0

for k in range(1, n):
    A_k = sequence[:k]
    B_k = sequence[k:]

    lcm_A = lcm_list(A_k)
    gcd_B = gcd_list(B_k)

    is_good = lcm_A == gcd_B

    print(f"k={k}: A_k={A_k}, B_k={B_k}. LCM(A_k)={lcm_A}, GCD(B_k)={gcd_B}. Good: {is_good}")
    if is_good:
        good_partitions += 1

print(f"Total good partitions for {sequence}: {good_partitions}")
